// ① 服务器源码（排除 data / __pycache__ / 日志 / ota 固件）
const SRV = 'E:\\zhixiaoban_prj\\plant_server';
function copyTree(src, dst, skip) {
  let n = 0;
  for (const e of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, e.name), d = path.join(dst, e.name);
    const rel = path.relative(SRV, s);
    if (skip(rel, e)) continue;
    if (e.isDirectory()) { fs.mkdirSync(d, { recursive: true }); n += copyTree(s, d, skip); }
    else { fs.copyFileSync(s, d); n++; }
  }
  return n;
}
const nSrv = copyTree(SRV, path.join(ROOT, '01_源码\\服务器'), (rel, e) => {
  if (e.isDirectory()) return ['data', '__pycache__', 'ota', '.git'].includes(e.name);
  if (e.name.startsWith('server_err') || e.name.startsWith('server_out')) return true;
  if (e.name.endsWith('.pyc')) return true;
  if (e.name.endsWith('.apk')) return true;   // APK 放 05_产物
  if (e.name.endsWith('.db') || e.name.endsWith('.db-wal') || e.name.endsWith('.db-shm')) return true;
  return false;
});
console.log('服务器文件:', nSrv);

// ② 安卓壳工程
const AND = 'E:\\zhixiaoban_prj\\plant_android';
let nAnd = 0;
function copyAll(src, dst, skipName) {
  fs.mkdirSync(dst, { recursive: true });
  for (const e of fs.readdirSync(src, { withFileTypes: true })) {
    if (skipName && skipName(e.name)) continue;
    const s = path.join(src, e.name), d = path.join(dst, e.name);
    if (e.isDirectory()) copyAll(s, d, skipName);
    else { fs.copyFileSync(s, d); nAnd++; }
  }
}
copyAll(AND, path.join(ROOT, '01_源码\\手机端-安卓壳'), (n) => n === 'build');
console.log('安卓壳文件:', nAnd);", "title": "Copy server and android sources"}

