{"code": "const fs = await import('node:fs');
const crypto = await import('node:crypto');
const path = await import('node:path');
const ROOT = 'E:\\zhixiaoban_prj\\植小伴_调试归档_20260912_当前版本全量';
function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out); else out.push(p);
  }
  return out;
}
const files = walk(ROOT).sort();
const lines = [];
let total = 0;
for (const f of files) {
  if (path.basename(f) === 'SHA256SUMS.txt') continue;
  const buf = fs.readFileSync(f);
  total += buf.length;
  lines.push(crypto.createHash('sha256').update(buf).digest('hex') + '  ' +
             path.relative(ROOT, f).split(path.sep).join('/'));
}
fs.writeFileSync(path.join(ROOT, 'SHA256SUMS.txt'), lines.join('\n') + '\n', 'utf8');
console.log('文件数:', lines.length, ' 总计:', (total / 1048576).toFixed(2), 'MB');
// 目录树概览
const top = fs.readdirSync(ROOT);
for (const t of top) {
  const p = path.join(ROOT, t);
  if (fs.statSync(p).isDirectory()) {
    const sub = walk(p);
    console.log('  ' + t + '  (' + sub.length + ' 文件)');
    const dirs = fs.readdirSync(p).filter(x => fs.statSync(path.join(p, x)).isDirectory());
    for (const d of dirs) console.log('      ' + d + '/  (' + walk(path.join(p, d)).length + ')');
  } else {
    console.log('  ' + t);
  }
}", "title": "Generate SHA256SUMS and tree"}

