// SHA256SUMS
const crypto = await import('node:crypto');
const path = await import('node:path');
function walk(d, out) { for (const f of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, f.name); if (f.isDirectory()) walk(p, out); else if (!/^SHA256SUMS\.txt$/.test(f.name)) out.push(p); } return out; }
const files = walk(DST, []).sort();
const lines = files.map(p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex') + '  ' + path.relative(DST, p).split(path.sep).join('/'));
fs.writeFileSync(DST + '/SHA256SUMS.txt', lines.join('\n') + '\n', 'utf8');
nodeRepl.write('SHA256SUMS 已生成：' + lines.length + ' 条\n');
nodeRepl.write(fs.readFileSync(DST + '/SHA256SUMS.txt', 'utf8').split('\n').slice(0, 3).join('\n'));", "title": "生成校验清单"}

